public final class Program {
    public static Object signIn(Object request, Object deps) {
        var __f = FddVerify.frame("bp-auth-login");
        __f.enter("NODE-AUTH-LOGIN-001");
        Object email = get(get(request, "body"), "email");
        Object emailCheck = checkEmail(email, "email");
        Object password = get(get(request, "body"), "password");
        __f.enter("NODE-AUTH-LOGIN-006");
        if (!(bool(get(emailCheck, "valid")) && !isEmpty(password))) {
            __f.enter("NODE-AUTH-LOGIN-009");
            return obj(
                "status", 401d,
                "body", obj(
                    "error", bool(get(emailCheck, "valid")) ? get(checkRequired(password, "password"), "message") : get(emailCheck, "message")));
        }
        __f.enter("NODE-AUTH-LOGIN-010");
        Object lookUpUser = FddVerify.dep("userService", "getUsersByEmail", "NODE-AUTH-LOGIN-010", obj("query", omitNulls(obj("email", email))));
        Object status1 = get(lookUpUser, "status");
        if (eq(status1, 200d)) {
            __f.enter("NODE-AUTH-LOGIN-014");
            if (!eq(get(get(lookUpUser, "body"), "passwordHash"), format("hash:{password}", obj("password", password)))) {
                __f.enter("NODE-AUTH-LOGIN-021");
                return obj("status", 401d, "body", obj("error", "Invalid credentials"));
            }
            Object id = get(get(lookUpUser, "body"), "id");
            __f.enter("NODE-AUTH-LOGIN-018");
            FddVerify.dep("eventBus", "publishUserLoggedIn", "NODE-AUTH-LOGIN-018", obj("userId", id));
            __f.enter("NODE-AUTH-LOGIN-019");
            return obj(
                "status", 200d,
                "body", obj(
                    "accessToken", format("TEST-TOKEN-{id}", obj("id", id)),
                    "refreshToken", "REFRESH-TOKEN",
                    "expiresIn", 3600d,
                    "tokenType", "Bearer"));
        } else if (eq(status1, 404d)) {
            __f.enter("NODE-AUTH-LOGIN-022");
            return obj("status", 401d, "body", obj("error", "Invalid credentials"));
        } else {
            __f.enter("NODE-AUTH-LOGIN-023");
            throw new FddError("UPSTREAM_ERROR", "User Service failed");
        }
    }
}

