// Runtime for code generated by Rabbinatix from Logic Blueprints. Do not edit: it is regenerated on export.
// Every helper mirrors the simulator, so generated handlers behave exactly like their blueprints.
// Values are JSON values: Map<String, Object>, List<Object>, String, Double, Boolean and null.
package fddcheck;

import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Constructor;
import java.lang.reflect.Method;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.RecordComponent;
import java.lang.reflect.Type;
import java.math.BigDecimal;
import java.math.MathContext;
import java.math.RoundingMode;
import java.nio.ByteBuffer;
import java.nio.charset.CharacterCodingException;
import java.nio.charset.CodingErrorAction;
import java.nio.charset.StandardCharsets;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Base64;
import java.util.Collection;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.function.BiFunction;
import java.util.function.BiPredicate;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

/** The helpers the generated handlers call (import static ...FddRuntime.*) and the types they use. */
@SuppressWarnings("unchecked")
public final class FddRuntime {
    private FddRuntime() {
    }

    /** An error with a code, like the simulator's errors (Throw nodes, DIVIDE_BY_ZERO, INVALID_JSON...). */
    public static final class FddError extends RuntimeException {
        private static final long serialVersionUID = 1L;
        private final String code;

        public FddError(Object code, Object message) {
            super(asString(message));
            this.code = asString(code);
        }

        public String getCode() {
            return code;
        }
    }

    /** A local variable that a lambda (a parallel branch, a callback) changes. */
    public static final class Cell {
        public Object v;

        public Cell(Object v) {
            this.v = v;
        }
    }

    /** An item of a list with its position, for loops that read both. */
    public record Indexed(Object index, Object item) {
    }

    /** The JSON field name of a record component, when it isn't the component's own name. */
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.RECORD_COMPONENT)
    public @interface Key {
        String value();
    }

    /** Converts between your own types (records, lists, maps) and the JSON values the handlers take and return. */
    public static final class FddJson {
        private FddJson() {
        }

        /** A record, list, map or plain value as JSON values. */
        public static Object toValue(Object value) {
            if (value == null || value instanceof String || value instanceof Boolean) return value;
            if (value instanceof Number n) return n.doubleValue();
            if (value instanceof Character c) return String.valueOf(c);
            if (value instanceof Enum<?> e) return e.name();
            if (value instanceof Map<?, ?> m) {
                Map<String, Object> out = new LinkedHashMap<>();
                for (Map.Entry<?, ?> e : m.entrySet()) out.put(String.valueOf(e.getKey()), toValue(e.getValue()));
                return out;
            }
            if (value instanceof Collection<?> c) {
                List<Object> out = new ArrayList<>();
                for (Object x : c) out.add(toValue(x));
                return out;
            }
            if (value instanceof Object[] a) return toValue(Arrays.asList(a));
            if (value.getClass().isRecord()) {
                Map<String, Object> out = new LinkedHashMap<>();
                for (RecordComponent rc : value.getClass().getRecordComponents()) {
                    try {
                        Method get = rc.getAccessor();
                        get.setAccessible(true);
                        out.put(jsonName(rc), toValue(get.invoke(value)));
                    } catch (ReflectiveOperationException e) {
                        throw new IllegalStateException(e);
                    }
                }
                return out;
            }
            return value.toString();
        }

        /** JSON values as a record (or a list, a map, a plain value) of the given type. */
        public static <T> T fromValue(Object value, Class<T> type) {
            return (T) convert(value, type);
        }

        /** JSON text as JSON values; fails with IllegalArgumentException. */
        public static Object parse(String json) {
            return new JsonReader(json).document();
        }

        /** JSON values as JSON text (JSON.stringify). */
        public static String stringify(Object value) {
            return json(value);
        }

        private static String jsonName(RecordComponent rc) {
            Key k = rc.getAnnotation(Key.class);
            return k != null ? k.value() : rc.getName();
        }

        private static Object convert(Object v, Type type) {
            if (type instanceof ParameterizedType p) {
                Class<?> raw = (Class<?>) p.getRawType();
                Type[] args = p.getActualTypeArguments();
                if (v != null && Collection.class.isAssignableFrom(raw)) {
                    List<Object> out = new ArrayList<>();
                    for (Object x : asArray(v)) out.add(convert(x, args[0]));
                    return out;
                }
                if (v != null && Map.class.isAssignableFrom(raw)) {
                    Map<String, Object> out = new LinkedHashMap<>();
                    if (v instanceof Map<?, ?> m) for (Map.Entry<?, ?> e : m.entrySet()) out.put(String.valueOf(e.getKey()), convert(e.getValue(), args[1]));
                    return out;
                }
                return convert(v, raw);
            }
            if (!(type instanceof Class<?> c) || c == Object.class) return v;
            if (v == null) {
                if (c == boolean.class) return false;
                if (c == double.class) return 0d;
                if (c == long.class) return 0L;
                if (c == int.class) return 0;
                return null;
            }
            if (c == String.class) return v instanceof String ? v : jsString(v);
            if (c == Double.class || c == double.class) return toNum(v);
            if (c == Long.class || c == long.class) return (long) toNum(v);
            if (c == Integer.class || c == int.class) return (int) toNum(v);
            if (c == Boolean.class || c == boolean.class) return truthy(v);
            if (c.isRecord()) {
                if (!(v instanceof Map<?, ?> m)) throw new IllegalArgumentException("Expected an object for " + c.getSimpleName());
                RecordComponent[] rcs = c.getRecordComponents();
                Object[] values = new Object[rcs.length];
                Class<?>[] types = new Class<?>[rcs.length];
                for (int i = 0; i < rcs.length; i++) {
                    types[i] = rcs[i].getType();
                    values[i] = convert(m.get(jsonName(rcs[i])), rcs[i].getGenericType());
                }
                try {
                    Constructor<?> ctor = c.getDeclaredConstructor(types);
                    ctor.setAccessible(true);
                    return ctor.newInstance(values);
                } catch (ReflectiveOperationException e) {
                    throw new IllegalStateException(e);
                }
            }
            return v;
        }
    }

    /** Strict JSON (what JSON.parse accepts); numbers become doubles. */
    private static final class JsonReader {
        private final String s;
        private int i;

        JsonReader(String s) {
            this.s = s;
        }

        Object document() {
            ws();
            Object v = value();
            ws();
            if (i != s.length()) throw bad();
            return v;
        }

        private IllegalArgumentException bad() {
            return new IllegalArgumentException("Not valid JSON at " + i);
        }

        private void ws() {
            while (i < s.length()) {
                char c = s.charAt(i);
                if (c != ' ' && c != '\t' && c != '\n' && c != '\r') break;
                i++;
            }
        }

        private char peek() {
            if (i >= s.length()) throw bad();
            return s.charAt(i);
        }

        private Object value() {
            char c = peek();
            if (c == '{') return object();
            if (c == '[') return array();
            if (c == '"') return string();
            if (c == 't') return word("true", Boolean.TRUE);
            if (c == 'f') return word("false", Boolean.FALSE);
            if (c == 'n') return word("null", null);
            return number();
        }

        private Object word(String w, Object v) {
            if (!s.startsWith(w, i)) throw bad();
            i += w.length();
            return v;
        }

        private Map<String, Object> object() {
            Map<String, Object> m = new LinkedHashMap<>();
            i++;
            ws();
            if (peek() == '}') {
                i++;
                return m;
            }
            for (;;) {
                ws();
                if (peek() != '"') throw bad();
                String k = string();
                ws();
                if (peek() != ':') throw bad();
                i++;
                ws();
                m.put(k, value());
                ws();
                char c = peek();
                i++;
                if (c == '}') return m;
                if (c != ',') throw bad();
            }
        }

        private List<Object> array() {
            List<Object> l = new ArrayList<>();
            i++;
            ws();
            if (peek() == ']') {
                i++;
                return l;
            }
            for (;;) {
                ws();
                l.add(value());
                ws();
                char c = peek();
                i++;
                if (c == ']') return l;
                if (c != ',') throw bad();
            }
        }

        private String string() {
            i++;
            StringBuilder sb = new StringBuilder();
            for (;;) {
                char c = peek();
                i++;
                if (c == '"') return sb.toString();
                if (c < 0x20) throw bad();
                if (c != '\\') {
                    sb.append(c);
                    continue;
                }
                char e = peek();
                i++;
                switch (e) {
                    case '"', '\\', '/' -> sb.append(e);
                    case 'b' -> sb.append('\b');
                    case 'f' -> sb.append('\f');
                    case 'n' -> sb.append('\n');
                    case 'r' -> sb.append('\r');
                    case 't' -> sb.append('\t');
                    case 'u' -> {
                        if (i + 4 > s.length()) throw bad();
                        int code = 0;
                        for (int k = 0; k < 4; k++) {
                            int d = Character.digit(s.charAt(i++), 16);
                            if (d < 0) throw bad();
                            code = code * 16 + d;
                        }
                        sb.append((char) code);
                    }
                    default -> throw bad();
                }
            }
        }

        private Object number() {
            int start = i;
            if (i < s.length() && s.charAt(i) == '-') i++;
            if (i < s.length() && s.charAt(i) == '0') i++;
            else if (!digits()) throw bad();
            if (i < s.length() && s.charAt(i) == '.') {
                i++;
                if (!digits()) throw bad();
            }
            if (i < s.length() && (s.charAt(i) == 'e' || s.charAt(i) == 'E')) {
                i++;
                if (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) i++;
                if (!digits()) throw bad();
            }
            return Double.parseDouble(s.substring(start, i));
        }

        private boolean digits() {
            int start = i;
            while (i < s.length() && s.charAt(i) >= '0' && s.charAt(i) <= '9') i++;
            return i > start;
        }
    }

    // ---------- the value model the generated code uses ----------

    /** A condition: true only for true, else JavaScript truthiness. */
    public static boolean bool(Object v) {
        return v instanceof Boolean b ? b : truthy(v);
    }

    /** A number operand. */
    public static double num(Object v) {
        return v instanceof Number n ? n.doubleValue() : toNum(v);
    }

    /** o.name, null-safe: null when o is null or has no such field. */
    public static Object get(Object o, String name) {
        return key(o, name);
    }

    /** o[key], null-safe. */
    public static Object item(Object o, Object k) {
        return key(o, k);
    }

    /** An object from key, value, key, value... */
    public static Map<String, Object> obj(Object... fields) {
        Map<String, Object> d = new LinkedHashMap<>();
        for (int i = 0; i + 1 < fields.length; i += 2) d.put((String) fields[i], fields[i + 1]);
        return d;
    }

    public static List<Object> arr(Object... items) {
        return new ArrayList<>(Arrays.asList(items));
    }

    /** a ?? b (b already evaluated). */
    public static Object orElse(Object a, Object b) {
        return a != null ? a : b;
    }

    /** a ?? b (b evaluated only when a is null). */
    public static Object orElseGet(Object a, Supplier<Object> b) {
        return a != null ? a : b.get();
    }

    /** a === b for strings, numbers, booleans and null. */
    public static boolean eq(Object a, Object b) {
        if (a == null) return b == null;
        if (a instanceof Number x) return b instanceof Number y && x.doubleValue() == y.doubleValue();
        if (a instanceof String s) return b instanceof String t && s.equals(t);
        if (a instanceof Boolean p) return b instanceof Boolean q && p.booleanValue() == q.booleanValue();
        return a == b;
    }

    public static List<Object> iter(Object v) {
        return v instanceof List<?> l ? (List<Object>) l : new ArrayList<>();
    }

    public static List<Indexed> indexed(Object v) {
        List<Object> l = iter(v);
        List<Indexed> out = new ArrayList<>();
        for (int i = 0; i < l.size(); i++) out.add(new Indexed((double) i, l.get(i)));
        return out;
    }

    public static List<Object> map(Object items, BiFunction<Object, Object, Object> fn) {
        List<Object> list = asArray(items);
        List<Object> out = new ArrayList<>();
        for (int i = 0; i < list.size(); i++) out.add(fn.apply(list.get(i), (double) i));
        return out;
    }

    public static List<Object> filter(Object items, BiPredicate<Object, Object> fn) {
        List<Object> list = asArray(items);
        List<Object> out = new ArrayList<>();
        for (int i = 0; i < list.size(); i++) if (fn.test(list.get(i), (double) i)) out.add(list.get(i));
        return out;
    }

    public static Object find(Object items, BiPredicate<Object, Object> fn) {
        List<Object> list = asArray(items);
        for (int i = 0; i < list.size(); i++) if (fn.test(list.get(i), (double) i)) return list.get(i);
        return null;
    }

    public static boolean some(Object items, BiPredicate<Object, Object> fn) {
        List<Object> list = asArray(items);
        for (int i = 0; i < list.size(); i++) if (fn.test(list.get(i), (double) i)) return true;
        return false;
    }

    public static boolean every(Object items, BiPredicate<Object, Object> fn) {
        List<Object> list = asArray(items);
        for (int i = 0; i < list.size(); i++) if (!fn.test(list.get(i), (double) i)) return false;
        return true;
    }

    private static Object key(Object o, Object k) {
        if (o instanceof Map<?, ?> d) return d.get(k instanceof String s ? s : asString(k));
        if (o instanceof List<?> l) {
            if ("length".equals(k)) return (double) l.size();
            int i = index(k);
            return i >= 0 && i < l.size() ? l.get(i) : null;
        }
        if (o instanceof String s) {
            if ("length".equals(k)) return (double) s.length();
            int j = index(k);
            return j >= 0 && j < s.length() ? String.valueOf(s.charAt(j)) : null;
        }
        return null;
    }

    private static boolean asciiDigits(String s) {
        if (s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) if (s.charAt(i) < '0' || s.charAt(i) > '9') return false;
        return true;
    }

    /** A list position, or -1. */
    private static int index(Object k) {
        double d;
        if (k instanceof Number n) d = n.doubleValue();
        else if (k instanceof String s && asciiDigits(s)) d = Double.parseDouble(s);
        else return -1;
        return d >= 0 && d < Integer.MAX_VALUE && Math.floor(d) == d ? (int) d : -1;
    }

    private static double trunc(double d) {
        return d < 0 ? Math.ceil(d) : Math.floor(d);
    }

    // ---------- JavaScript conversions ----------

    /** A number as JavaScript's String(n) writes it. */
    public static String numText(double n) {
        if (Double.isNaN(n)) return "NaN";
        if (Double.isInfinite(n)) return n > 0 ? "Infinity" : "-Infinity";
        if (n == 0) return "0";
        if (Math.abs(n) < 1e15 && Math.floor(n) == n) return Long.toString((long) n);
        // the shortest digits that read back as the same double
        BigDecimal exact = new BigDecimal(Math.abs(n));
        BigDecimal b = exact;
        for (int p = 1; p <= 17; p++) {
            BigDecimal c = exact.round(new MathContext(p, RoundingMode.HALF_EVEN));
            if (c.doubleValue() == Math.abs(n)) {
                b = c;
                break;
            }
        }
        String digits = b.unscaledValue().toString();
        int point = digits.length() - b.scale();
        int end = digits.length();
        while (end > 1 && digits.charAt(end - 1) == '0') end--;
        digits = digits.substring(0, end);
        int k = digits.length();
        String sign = n < 0 ? "-" : "";
        if (k <= point && point <= 21) return sign + digits + "0".repeat(point - k);
        if (0 < point && point <= 21) return sign + digits.substring(0, point) + "." + digits.substring(point);
        if (-6 < point && point <= 0) return sign + "0." + "0".repeat(-point) + digits;
        int x = point - 1;
        return sign + digits.charAt(0) + (k > 1 ? "." + digits.substring(1) : "") + "e" + (x >= 0 ? "+" : "-") + Math.abs(x);
    }

    /** String(v). */
    public static String jsString(Object v) {
        if (v == null) return "null";
        if (v instanceof Boolean b) return b ? "true" : "false";
        if (v instanceof Number d) return numText(d.doubleValue());
        if (v instanceof String s) return s;
        if (v instanceof List<?> l) {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < l.size(); i++) {
                if (i > 0) sb.append(',');
                if (l.get(i) != null) sb.append(jsString(l.get(i)));
            }
            return sb.toString();
        }
        if (v instanceof Map<?, ?>) return "[object Object]";
        return String.valueOf(v);
    }

    /** JSON.stringify. */
    public static String json(Object v) {
        StringBuilder sb = new StringBuilder();
        write(sb, v);
        return sb.toString();
    }

    private static void write(StringBuilder sb, Object v) {
        if (v == null) sb.append("null");
        else if (v instanceof Boolean b) sb.append(b ? "true" : "false");
        else if (v instanceof Number n) {
            double d = n.doubleValue();
            sb.append(Double.isFinite(d) ? numText(d) : "null");
        } else if (v instanceof String s) quote(sb, s);
        else if (v instanceof List<?> l) {
            sb.append('[');
            for (int i = 0; i < l.size(); i++) {
                if (i > 0) sb.append(',');
                write(sb, l.get(i));
            }
            sb.append(']');
        } else if (v instanceof Map<?, ?> d) {
            sb.append('{');
            boolean first = true;
            for (Map.Entry<?, ?> e : d.entrySet()) {
                if (!first) sb.append(',');
                first = false;
                quote(sb, String.valueOf(e.getKey()));
                sb.append(':');
                write(sb, e.getValue());
            }
            sb.append('}');
        } else quote(sb, String.valueOf(v));
    }

    private static void quote(StringBuilder sb, String s) {
        sb.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                case '\b' -> sb.append("\\b");
                case '\f' -> sb.append("\\f");
                default -> {
                    if (c < 0x20) sb.append(String.format("\\u%04x", (int) c));
                    else sb.append(c);
                }
            }
        }
        sb.append('"');
    }

    /** JavaScript's white space and line terminators (what String.prototype.trim removes). */
    private static boolean jsSpace(char c) {
        return c == ' ' || (c >= 0x09 && c <= 0x0d) || c == 0xa0 || c == 0x1680 || (c >= 0x2000 && c <= 0x200a) || c == 0x2028 || c == 0x2029
            || c == 0x202f || c == 0x205f || c == 0x3000 || c == 0xfeff;
    }

    private static String jsTrim(String s) {
        int a = 0, b = s.length();
        while (a < b && jsSpace(s.charAt(a))) a++;
        while (b > a && jsSpace(s.charAt(b - 1))) b--;
        return s.substring(a, b);
    }

    private static final Pattern DECIMAL = Pattern.compile("^[+-]?(\\d+\\.?\\d*|\\.\\d+)([eE][+-]?\\d+)?$");

    /** Number(v). */
    public static double jsNumber(Object v) {
        if (v == null) return 0;
        if (v instanceof Boolean b) return b ? 1 : 0;
        if (v instanceof Number d) return d.doubleValue();
        if (v instanceof String s) {
            String t = jsTrim(s);
            if (t.isEmpty()) return 0;
            if (t.length() > 2 && t.charAt(0) == '0' && "xXoObB".indexOf(t.charAt(1)) >= 0) {
                char r = Character.toLowerCase(t.charAt(1));
                int radix = r == 'x' ? 16 : r == 'o' ? 8 : 2;
                double acc = 0;
                for (int i = 2; i < t.length(); i++) {
                    int dgt = Character.digit(t.charAt(i), radix);
                    if (dgt < 0 || t.charAt(i) > 'z') return Double.NaN;
                    acc = acc * radix + dgt;
                }
                return acc;
            }
            if (t.equals("Infinity") || t.equals("+Infinity")) return Double.POSITIVE_INFINITY;
            if (t.equals("-Infinity")) return Double.NEGATIVE_INFINITY;
            return DECIMAL.matcher(t).matches() ? Double.parseDouble(t) : Double.NaN;
        }
        if (v instanceof List<?> l) {
            if (l.isEmpty()) return 0;
            Object x = l.get(0);
            return l.size() == 1 && !(x instanceof List<?> || x instanceof Map<?, ?>) ? jsNumber(x == null ? "" : x) : Double.NaN;
        }
        return Double.NaN;
    }

    private static Object prim(Object x) {
        return x instanceof List<?> || x instanceof Map<?, ?> ? jsString(x) : x;
    }

    private static boolean lt(Object a, Object b) {
        if (a instanceof String s && b instanceof String t) return s.compareTo(t) < 0;
        return jsNumber(prim(a)) < jsNumber(prim(b));
    }

