        if (a instanceof List<?> l && b instanceof List<?> m) {
            if (l.size() != m.size()) return false;
            for (int i = 0; i < l.size(); i++) if (!deepEqual(l.get(i), m.get(i))) return false;
            return true;
        }
        if (a instanceof Map<?, ?> d && b instanceof Map<?, ?> e) {
            if (d.size() != e.size()) return false;
            for (Map.Entry<?, ?> p : d.entrySet()) if (!e.containsKey(p.getKey()) || !deepEqual(p.getValue(), e.get(p.getKey()))) return false;
            return true;
        }
        return eq(a, b);
    }

