    // ---------- paths & objects ----------

    private static final Pattern SEGMENT = Pattern.compile("([^\\[\\]]+)|\\[(\\d+)\\]");

    /** user.roles[0].name: segments (String or Integer). */
    public static List<Object> pathSegments(String path) {
        List<Object> out = new ArrayList<>();
        for (String part : path.split("\\.")) {
            if (part.isEmpty()) continue;
            Matcher m = SEGMENT.matcher(part);
            while (m.find()) out.add(m.group(1) != null ? m.group(1) : (Object) Integer.parseInt(m.group(2)));
        }
        return out;
    }

    private static boolean unsafePath(List<Object> segs) {
        for (Object s : segs) if ("__proto__".equals(s) || "constructor".equals(s) || "prototype".equals(s)) return true;
        return false;
    }

    private static Object seg(Object s) {
        return s instanceof Integer i ? (Object) (double) i : s;
    }

    private static String segKey(Object s) {
        return s instanceof Integer i ? Integer.toString(i) : (String) s;
    }

    /** The path exists (its value may be null). */
    public static boolean hasPath(Object value, Object path) {
        String p = str(path);
        if (p.isEmpty() || p.equals("$")) return true;
        List<Object> segs = pathSegments(p);
        if (unsafePath(segs)) return false;
        Object cur = value;
        for (Object s : segs) {
            if (cur instanceof Map<?, ?> d) {
                String k = segKey(s);
                if (!d.containsKey(k)) return false;
                cur = d.get(k);
            } else if (cur instanceof List<?> l) {
                if ("length".equals(s)) cur = (double) l.size();
                else if (s instanceof Integer i && i < l.size()) cur = l.get(i);
                else return false;
            } else if (cur instanceof String str) {
                if ("length".equals(s)) cur = (double) str.length();
                else if (s instanceof Integer j && j < str.length()) cur = String.valueOf(str.charAt(j));
                else return false;
            } else return false;
        }
        return true;
    }

    /** Reads a nested value; null when a step is missing. */
    public static Object getPath(Object value, Object path) {
        String p = str(path);
        if (p.isEmpty() || p.equals("$")) return value;
        List<Object> segs = pathSegments(p);
        if (unsafePath(segs)) return null;
        Object cur = value;
        for (Object s : segs) {
            if (cur == null) return null;
            cur = key(cur, seg(s));
        }
        return cur;
    }

    /** A path that isn't there (JavaScript's undefined): left out of objects, like JSON.stringify does. */
    private static final Object MISSING = new Object();

    private static Object lookup(Object value, String path) {
        return hasPath(value, path) ? getPath(value, path) : MISSING;
    }

    private static boolean container(Object v) {
        return v instanceof List<?> || v instanceof Map<?, ?>;
    }

    private static Object copy(Object v) {
        if (v instanceof List<?> l) return new ArrayList<Object>(l);
        if (v instanceof Map<?, ?> d) return new LinkedHashMap<>((Map<String, Object>) d);
        return v;
    }

    /** A copy with a nested value set. */
    public static Object setPath(Object value, Object path, Object v) {
        List<Object> segs = pathSegments(str(path));
        if (segs.isEmpty()) return v;
        Object root = container(value) ? copy(value) : new LinkedHashMap<String, Object>();
        if (unsafePath(segs)) return root;
        Object cur = root;
        for (int i = 0; i < segs.size(); i++) {
            Object s = segs.get(i);
            boolean last = i == segs.size() - 1;
            if (cur instanceof List<?> && s instanceof Integer n) {
                List<Object> l = (List<Object>) cur;
                while (l.size() <= n) l.add(null);
                if (last) {
                    if (v != MISSING) l.set(n, v);
                    break;
                }
                Object c = copy(l.get(n));
                Object next = container(c) ? c : segs.get(i + 1) instanceof Integer ? new ArrayList<Object>() : new LinkedHashMap<String, Object>();
                l.set(n, next);
                cur = next;
            } else {
                Map<String, Object> d = cur instanceof Map<?, ?> ? (Map<String, Object>) cur : new LinkedHashMap<>();
                String k = segKey(s);
                if (last) {
                    if (v != MISSING) d.put(k, v);
                    break;
                }
                Object c = d.containsKey(k) ? copy(d.get(k)) : null;
                Object next = container(c) ? c : segs.get(i + 1) instanceof Integer ? new ArrayList<Object>() : new LinkedHashMap<String, Object>();
                d.put(k, next);
                cur = next;
            }
        }
        return root;
    }

    private static Object deepClone(Object v) {
        if (v instanceof List<?> l) {
            List<Object> out = new ArrayList<>();
            for (Object x : l) out.add(deepClone(x));
            return out;
        }
        if (v instanceof Map<?, ?> d) {
            Map<String, Object> out = new LinkedHashMap<>();
            for (Map.Entry<?, ?> e : d.entrySet()) out.put((String) e.getKey(), deepClone(e.getValue()));
            return out;
        }
        return v;
    }

    /** A copy without a nested value. */
    public static Object removePath(Object value, Object path) {
        List<Object> segs = pathSegments(str(path));
        if (segs.isEmpty() || !container(value)) return value;
        Object clone = deepClone(value);
        if (unsafePath(segs)) return clone;
        Object cur = clone;
        for (Object s : segs.subList(0, segs.size() - 1)) {
            Object next = null;
            if (cur instanceof Map<?, ?> map && map.containsKey(segKey(s))) next = map.get(segKey(s));
            else if (cur instanceof List<?> list && s instanceof Integer i && i < list.size()) next = list.get(i);
            if (!container(next)) return clone;
            cur = next;
        }
        Object lastSeg = segs.get(segs.size() - 1);
        if (cur instanceof List<?> l && lastSeg instanceof Integer n) {
            if (n < l.size()) l.remove((int) n);
        } else if (cur instanceof Map<?, ?> d) d.remove(segKey(lastSeg));
        return clone;
    }

    private static Map<String, Object> spread(Object v) {
        Map<String, Object> out = new LinkedHashMap<>();
        if (v instanceof Map<?, ?> d) return (Map<String, Object>) d;
        if (v instanceof List<?> l) for (int i = 0; i < l.size(); i++) out.put(Integer.toString(i), l.get(i));
        if (v instanceof String s) for (int i = 0; i < s.length(); i++) out.put(Integer.toString(i), String.valueOf(s.charAt(i)));
        return out;
    }

    /** Shallow merge, B over A. */
    public static Map<String, Object> merge(Object a, Object b) {
        Map<String, Object> d = new LinkedHashMap<>(spread(a));
        d.putAll(spread(b));
        return d;
