    /** New object: target path from source path. */
    public static Object transform(Object source, Object mapping) {
        Object out = new LinkedHashMap<String, Object>();
        for (Object pair : asArray(mapping)) {
            List<Object> p = asArray(pair);
            out = setPath(out, p.isEmpty() ? null : p.get(0), lookup(source, str(p.size() > 1 ? p.get(1) : null)));
        }
        return out;
    }

    private static final Pattern PLACEHOLDER = Pattern.compile("\\{\\{\\s*([^}]+?)\\s*\\}\\}");
    private static final Pattern WHOLE_PLACEHOLDER = Pattern.compile("^\\{\\{\\s*([^}]+?)\\s*\\}\\}$");

    /** Fills {{path}} placeholders from data. */
    public static Object template(Object value, Object data) {
        Object r = fill(value, data);
        return r == MISSING ? null : r;
    }

    private static Object fill(Object value, Object data) {
        if (value instanceof String s) {
            Matcher whole = WHOLE_PLACEHOLDER.matcher(s);
            if (whole.matches()) return lookup(data, whole.group(1));
            Matcher m = PLACEHOLDER.matcher(s);
            StringBuilder sb = new StringBuilder();
            while (m.find()) {
                Object r = getPath(data, m.group(1));
                m.appendReplacement(sb, Matcher.quoteReplacement(r == null ? "" : container(r) ? json(r) : jsString(r)));
            }
            m.appendTail(sb);
            return sb.toString();
        }
        if (value instanceof List<?> l) {
            List<Object> out = new ArrayList<>();
            for (Object x : l) {
                Object y = fill(x, data);
                out.add(y == MISSING ? null : y);
            }
            return out;
        }
        if (value instanceof Map<?, ?> d) {
            Map<String, Object> o = new LinkedHashMap<>();
            for (Map.Entry<?, ?> e : d.entrySet()) {
                Object y = fill(e.getValue(), data);
                if (y != MISSING) o.put((String) e.getKey(), y);
            }
            return o;
        }
        return value;
    }

