    private static Pattern rx(String pattern, String flags) {
        int o = 0;
        for (char c : flags.toCharArray()) {
            if ("gimsuyd".indexOf(c) < 0) throw new PatternSyntaxException("flags", flags, 0);
            if (c == 'i') o |= Pattern.CASE_INSENSITIVE | Pattern.UNICODE_CASE;
            if (c == 'm') o |= Pattern.MULTILINE;
            if (c == 's') o |= Pattern.DOTALL;
        }
        return Pattern.compile(pattern, o);
    }

    public static Map<String, Object> regexMatch(Object text, Object pattern, Object flags) {
        Pattern re;
        try {
            re = rx(str(pattern), str(flags));
        } catch (PatternSyntaxException e) {
            throw new FddError("INVALID_REGEX", "Invalid pattern " + str(pattern));
        }
        Matcher m = re.matcher(str(text));
        boolean found = m.find();
        List<Object> groups = new ArrayList<>();
        if (found) for (int i = 1; i <= m.groupCount(); i++) groups.add(m.group(i));
        return obj("matches", found, "groups", groups);
    }

