    public static List<Object> sortBy(Object a, Object path, Object desc) {
        int dir = bool(desc) ? -1 : 1;
        String p = str(path);
        List<Object> items = new ArrayList<>(asArray(a));
        // a stable sort, like Array.prototype.sort
        mergeSort(items, (x, y) -> {
            Object u = p.isEmpty() ? x : getPath(x, p), w = p.isEmpty() ? y : getPath(y, p);
            return lt(u, w) ? -dir : lt(w, u) ? dir : 0;
        });
        return items;
    }

    private static void mergeSort(List<Object> l, Comparator<Object> c) {
        if (l.size() < 2) return;
        int mid = l.size() / 2;
        List<Object> a = new ArrayList<>(l.subList(0, mid)), b = new ArrayList<>(l.subList(mid, l.size()));
        mergeSort(a, c);
        mergeSort(b, c);
        int i = 0, j = 0, k = 0;
        while (i < a.size() && j < b.size()) l.set(k++, c.compare(b.get(j), a.get(i)) < 0 ? b.get(j++) : a.get(i++));
        while (i < a.size()) l.set(k++, a.get(i++));
        while (j < b.size()) l.set(k++, b.get(j++));
    }

