    }

    /** First problem of a value against a shape, or null. */
    public static String checkValue(Object v, Object s, String path) {
        if (!(s instanceof Map<?, ?>) || eq(get(s, "type"), "any")) return null;
        Object type = get(s, "type");
        if (v == null) return bool(get(s, "nullable")) || eq(type, "null") ? null : path + " is null";
        String t = valueType(v);
        if (eq(type, "number") && (t.equals("integer") || t.equals("number"))) return null;
        if (!eq(type, t)) return path + ": expected " + str(type) + ", got " + t;
        if (get(s, "enum") instanceof List<?> en && !en.isEmpty()) {
            boolean found = false;
            for (Object x : en) found |= deepEqual(x, v);
            if (!found) {
                StringBuilder one = new StringBuilder();
                for (Object x : en) one.append(one.length() > 0 ? ", " : "").append(jsString(x));
                return path + ": " + json(v) + " is not one of " + one;
            }
        }
        if (t.equals("object") && get(s, "properties") instanceof Map<?, ?> props) {
            Map<?, ?> o = (Map<?, ?>) v;
            for (Map.Entry<?, ?> f : props.entrySet()) {
                String k = (String) f.getKey();
                if (!o.containsKey(k)) {
                    if (bool(get(f.getValue(), "required"))) return path + "." + k + " is missing";
                    continue;
                }
                String p = checkValue(o.get(k), f.getValue(), path + "." + k);
                if (p != null) return p;
            }
        }
        if (t.equals("array")) {
            List<?> l = (List<?>) v;
            for (int i = 0; i < l.size(); i++) {
                String p = checkValue(l.get(i), get(s, "items"), path + "[" + i + "]");
                if (p != null) return p;
            }
        }
        return null;
    }

