        long ms = needDate(date);
        long[] p = dateFields(ms);
        long day = Math.floorDiv(ms, DAY_MS) * DAY_MS;
        int u = PERIODS.indexOf(jsTrim(str(unit)).toLowerCase(Locale.ROOT));
        if (u < 0) throw new FddError("INVALID_UNIT", "Unknown period \"" + str(unit) + "\" (use hour, day, week, month or year)");
        long from, length;
        switch (u / 2) {
            case 0 -> { from = ms - p[8] % 3600000; length = 3600000L; }
            case 1 -> { from = day; length = DAY_MS; }
            case 2 -> { from = day - (p[7] + 6) % 7 * DAY_MS; length = 7 * DAY_MS; }
            case 3 -> { from = daysFromCivil(p[0], p[1], 1) * DAY_MS; length = daysIn(p[0], p[1]) * DAY_MS; }
            default -> { from = daysFromCivil(p[0], 1, 1) * DAY_MS; length = (daysFromCivil(p[0] + 1, 1, 1) - daysFromCivil(p[0], 1, 1)) * DAY_MS; }
        }
        return isoDate(end ? from + length - 1 : from);
    }

    /** The first moment of the period the date is in (UTC). */
    public static String startOf(Object date, Object unit) {
        return periodEdge(date, unit, false);
    }

    /** The last moment (...:59.999) of the period the date is in (UTC). */
    public static String endOf(Object date, Object unit) {
        return periodEdge(date, unit, true);
    }

    // ---------- runtime ----------

    /** Current date-time (ISO, like JavaScript's toISOString). */
    public static String now() {
        return isoDate(System.currentTimeMillis());
    }

    public static String uuid() {
        return UUID.randomUUID().toString();
    }

    /** Integer between min and max. */
    public static double random(Object min, Object max) {
        double lo = toNum(min), hi = toNum(max);
        return Math.floor(lo + ThreadLocalRandom.current().nextDouble() * (hi - lo + 1));
    }

    public static Object log(Object message) {
        System.out.println(message instanceof String s ? s : json(message));
        return null;
    }

    public static Object sleep(Object ms) {
        try {
            Thread.sleep((long) Math.max(0, toNum(ms)));
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new FddError("INTERRUPTED", "Interrupted while waiting");
        }
        return null;
    }

    /** Runs branches concurrently (one thread each) and waits for all; the first branch's error is rethrown. */
    public static void parallel(Runnable... branches) {
        Throwable[] errors = new Throwable[branches.length];
        Thread[] threads = new Thread[branches.length];
        for (int i = 0; i < branches.length; i++) {
            int k = i;
            threads[i] = new Thread(() -> {
                try {
                    branches[k].run();
                } catch (Throwable t) {
                    errors[k] = t;
                }
            });
            threads[i].start();
        }
        for (Thread t : threads) {
            try {
                t.join();
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new FddError("INTERRUPTED", "Interrupted while waiting");
            }
        }
        for (Throwable t : errors) {
            if (t instanceof RuntimeException r) throw r;
            if (t instanceof Error e) throw e;
        }
    }
}

